using Spectre.Console;

AnsiConsole.Markup("[bold green]Welcome to Spectre.Console![/]

");

// Render a table
var table = new Table();
table.AddColumn("Name");
table.AddColumn("Role");
table.AddColumn("Active");

table.AddRow("Alice", "Admin", "Yes");
table.AddRow("Bob", "User", "No");

table.Border(TableBorder.Rounded);
AnsiConsole.Write(table);

// Ask for input
string name = AnsiConsole.Prompt(
    new TextPrompt<string>("[yellow]What is your name?[/]"));
AnsiConsole.Markup($"Hello, [bold]{name}[/]!");

AnsiConsole.Progress()
    .AutoClear(false)
    .Columns(new ProgressColumn[]
    {
        new TaskDescriptionColumn(),
        new ProgressBarColumn(),
        new PercentageColumn(),
        new RemainingTimeColumn()
    })
    .Start(ctx =>
    {
        ProgressTask task = ctx.AddTask("Processing");
        task.MaxValue = 100;

        while (!ctx.IsFinished)
        {
            task.Increment(10);
            Thread.Sleep(200);
        }
    });
